// src/components/MyLibrary.js
import React, { useEffect, useState } from "react";
import api from "@landinghub/api";
import "../styles/MyLibrary.css";

const MyLibrary = () => {
  const [landings, setLandings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const token = localStorage.getItem("token");
    const userInfoRaw = localStorage.getItem("userInfo");
    if (!token || !userInfoRaw) {
      console.error("❌ Không tìm thấy userId hoặc token trong localStorage");
      setError("Bạn chưa đăng nhập hoặc token không hợp lệ");
      setLoading(false);
      return;
    }

    const userInfo = JSON.parse(userInfoRaw);
    const userId = userInfo?.userId;

    if (!userId) {
      console.error("❌ Không tìm thấy userId trong userInfo");
      setError("Thông tin người dùng không hợp lệ");
      setLoading(false);
      return;
    }

    // Gọi API lấy landing pages
    api
      .get(`/landing/my/${userId}`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => {
        console.log("✅ API trả về:", res.data);
        setLandings(res.data);
      })
      .catch((err) => {
        console.error("❌ Lỗi khi load MyLibrary:", err);
        setError("Không tải được danh sách landing. Vui lòng thử lại sau.");
      })
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p>Đang tải...</p>;
  if (error) return <p style={{ color: "red" }}>{error}</p>;
  if (!landings || landings.length === 0) {
    return (
      <div className="no-landing">
        <h2>Kho Landing Page của tôi</h2>
        <p>Chưa có landing nào được lưu.</p>
      </div>
    );
  }

  return (
    <div className="mylibrary">
      <h2>Kho Landing Page của tôi</h2>
      <div className="landing-list">
        {landings.map((item) => (
          <div key={item._id} className="landing-card">
            <img
              src={item.thumbnail || "/default-thumbnail.jpg"}
              alt={item.name}
              className="thumbnail"
            />
            <h3>{item.name}</h3>
            <a
              href={item.landingPageUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              Xem landing
            </a>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MyLibrary;
